# Generated by scripts/homebrew-formulas.py in tinhthanh/shipyard for v0.3.31-fork.11.
class Vetgo < Formula
  desc "Run coding agents on your own boxes: the berth CLI and laptop agent"
  homepage "https://github.com/tinhthanh/shipyard"
  version "0.3.31-fork.11"
  license "MIT"

  on_macos do
    on_arm do
      url "https://github.com/tinhthanh/shipyard/releases/download/v0.3.31-fork.11/berth-darwin-arm64.tar.gz"
      sha256 "5f463722832d2a589a02c2d0c24a1d01a428ce76708292e8cbff00c14be93065"
    end
    on_intel do
      url "https://github.com/tinhthanh/shipyard/releases/download/v0.3.31-fork.11/berth-darwin-amd64.tar.gz"
      sha256 "0b33ca13b2c41550717cde7543a7316bb3bc0aac1af31bbe192ab20953a6e8f2"
    end

    # The berthd builds `berth upgrade` puts on Mac boxes; the Linux ones
    # come in berth's own archive.
    resource "berthd-darwin-arm64" do
      url "https://github.com/tinhthanh/shipyard/releases/download/v0.3.31-fork.11/berthd-darwin-arm64.tar.gz"
      sha256 "79ca67ea07182512ad04a4d16938b97448049803a87b4f573d2ed4cbcc01d880"
    end
    resource "berthd-darwin-amd64" do
      url "https://github.com/tinhthanh/shipyard/releases/download/v0.3.31-fork.11/berthd-darwin-amd64.tar.gz"
      sha256 "93476c984644078d35f885b8d5079f5742ed0db2203bcbe11ea968f308f06971"
    end
  end
  on_linux do
    on_arm do
      url "https://github.com/tinhthanh/shipyard/releases/download/v0.3.31-fork.11/berth-linux-arm64.tar.gz"
      sha256 "3e670eaf77f25e1558597666766df0cb9e37b3658c5871f148e67b85b5303840"
    end
    on_intel do
      url "https://github.com/tinhthanh/shipyard/releases/download/v0.3.31-fork.11/berth-linux-amd64.tar.gz"
      sha256 "841691da0815220a394db2225658b7b08b2db6a8d012a45ffbec0c09c430e431"
    end
  end

  def install
    # berth looks beside its own file (through the link in bin) for the
    # berthd and tmux builds it uploads to boxes.
    libexec.install Dir["*"]
    if OS.mac?
      %w[arm64 amd64].each do |arch|
        resource("berthd-darwin-#{arch}").stage { libexec.install "berthd" => "berthd-darwin-#{arch}" }
      end
    end
    bin.install_symlink libexec/"berth"
  end

  def caveats
    <<~EOS
      Start the laptop agent, and have it start when you log in:
        berth agent install
      Add a box: berth add ssh USER@HOST (see berth help).
    EOS
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/berth version")
  end
end
